const server = app.listen(process.env.PORT || 3000);
let stopping = false;
process.on('SIGTERM', () => {
  if (stopping) return;
  stopping = true;
  server.close(async (error) => {
    await closeDatabasePool();
    if (error) process.exitCode = 1;
  });
});

